import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int dario = 0, xerxes = 0;

        for (int i = 0; i < N; i++) {
            int D = sc.nextInt();
            int X = sc.nextInt();
            if ((D + 2) % 5 == X) {
                dario++;
            } else {
                xerxes++;
            }
        }

        if (dario > xerxes) {
            System.out.println("dario");
        } else {
            System.out.println("xerxes");
        }

        sc.close();
    }
}
